'use strict';
const $=id=>document.getElementById(id), state={exp:'B',chart:'main'};
const mean=a=>a.reduce((s,x)=>s+x,0)/a.length;
const fmt=(x,d=2)=>x==null?'—':Number(x).toLocaleString('en-US',{maximumFractionDigits:d});
const levels=(rows,k)=>[...new Set(rows.map(r=>r[k]))].sort((a,b)=>typeof a==='number'?a-b:String(a).localeCompare(b));
function rows(){return LAB_DATA[state.exp].rows.filter(r=>!($('exclude').checked&&r.uncertain)&&($('third').value==='all'||r.third===$('third').value)&&($('block').value==='all'||r.block===$('block').value));}
function model(){return LAB_DATA[state.exp].models[$('exclude').checked?'exclude':'all'][$('response').value];}
function options(id,values){$(id).innerHTML='<option value="all">All</option>'+values.map(x=>`<option>${x}</option>`).join('');}
function changeExperiment(exp){state.exp=exp;document.querySelectorAll('[data-exp]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.exp===exp));$('response').innerHTML='<option value="failed">Failed count</option>'+(exp==='B'?'<option value="success">Successful count</option>':'');options('third',levels(LAB_DATA[exp].rows,'third'));options('block',levels(LAB_DATA[exp].rows,'block'));$('exclude').disabled=exp==='A';$('exclude').checked=false;$('download').href=`data/experiment-${exp.toLowerCase()}.csv`;render();}
function svgPlot(series,{xlabel='',ylabel='',width=850,height=320,scatter=false,zero=false}={}){
 const points=series.flatMap(s=>s.points),xs=points.map(p=>p.x),ys=points.map(p=>p.y);let xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys,zero?0:Infinity),ymax=Math.max(...ys,zero?0:-Infinity);if(xmin===xmax){xmin-=1;xmax+=1}if(ymin===ymax){ymin-=1;ymax+=1}let pad=(ymax-ymin)*.12;ymin-=pad;ymax+=pad;
 const X=x=>65+(x-xmin)/(xmax-xmin)*(width-95),Y=y=>height-55-(y-ymin)/(ymax-ymin)*(height-100);let s=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${ylabel} by ${xlabel}"><text x="65" y="18">${ylabel}</text>`;
 for(let i=0;i<5;i++){let y=ymin+(ymax-ymin)*i/4;s+=`<path d="M65 ${Y(y)} H${width-30}" stroke="#26364a"/><text x="54" y="${Y(y)+4}" text-anchor="end">${fmt(y,0)}</text>`;}
 if(zero)s+=`<path d="M65 ${Y(0)} H${width-30}" stroke="#f2bd71" stroke-dasharray="5 5"/>`;
 for(const x of [...new Set(xs)].sort((a,b)=>a-b).filter((_,i,a)=>a.length<=8||i%Math.ceil(a.length/5)===0))s+=`<text x="${X(x)}" y="${height-30}" text-anchor="middle">${series[0].labels?.[x]??fmt(x,0)}</text>`;
 series.forEach((g,j)=>{let color=g.color||['#71efdb','#f2bd71','#bdabff','#ed9eaf'][j%4];if(!scatter)s+=`<polyline points="${g.points.map(p=>`${X(p.x)},${Y(p.y)}`).join(' ')}" fill="none" stroke="${color}" stroke-width="2.5"/>`;for(const p of g.points)s+=`<circle class="point" tabindex="0" cx="${X(p.x)}" cy="${Y(p.y)}" r="4.5" fill="${color}"><title>${p.tip||g.name}: ${fmt(p.y)}${p.n?' · n='+p.n:''}</title></circle>`;s+=`<text x="${65+j*160}" y="${height-4}" style="fill:${color}">${g.name}</text>`;});return s+`<text x="${width-30}" y="${height-4}" text-anchor="end">${xlabel}</text></svg>`;
}
function grouped(rs,key,response){return levels(rs,key).map((v,i)=>{let a=rs.filter(r=>r[key]===v);return{x:typeof v==='number'?v:i,y:mean(a.map(r=>r[response])),n:a.length,tip:String(v)};});}
function drawChart(rs,response){let kind=state.chart;$('factor-label').hidden=kind!=='main';let title={main:'Main effects / observed marginal means',interaction:'Time × Power interaction',heat:'Treatment heatmap / observed means'}[kind];$('chart-title').textContent=title;$('chart-desc').textContent=`${response==='failed'?'Failed count, lower is better':'Successful count, higher is better'} · current selection ${rs.length} bags`;
 if(kind==='main'){let k=$('factor').value,lv=levels(rs,k);$('chart').innerHTML=svgPlot([{name:k,points:grouped(rs,k,response),labels:typeof lv[0]==='number'?null:Object.fromEntries(lv.map((x,i)=>[i,x]))}],{xlabel:k,ylabel:response+' / kernels'});}
 else if(kind==='interaction'){$('chart').innerHTML=svgPlot(levels(rs,'power').map(p=>({name:p,points:grouped(rs.filter(r=>r.power===p),'time',response)})),{xlabel:'Time / seconds',ylabel:response+' / kernels'});}
 else {let values=[];for(const power of ['High','Medium'])for(const time of [90,120,150]){const a=rs.filter(r=>r.time===time&&r.power===power);values.push({power,time,n:a.length,value:mean(a.map(r=>r[response]))});}let max=Math.max(...values.filter(v=>v.n).map(v=>v.value)),min=Math.min(...values.filter(v=>v.n).map(v=>v.value));$('chart').innerHTML='<div class="heat-grid"><span>Power / Time</span><span>90 s</span><span>120 s</span><span>150 s</span>'+['High','Medium'].map(p=>'<span>'+p+'</span>'+values.filter(v=>v.power===p).map(v=>`<button ${v.n?'':'disabled'} data-time="${v.time}" data-power="${p}" style="background:hsl(${response==='failed'?165-(v.value-min)/(max-min||1)*135:30+(v.value-min)/(max-min||1)*135} 35% 24%)" aria-label="${p} ${v.time} seconds mean ${fmt(v.value)}">${v.n?fmt(v.value):'No bags'}<br><small>n = ${v.n}</small></button>`).join('')).join('')+'</div>';document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>{$('time').value=b.dataset.time;$('power').value=b.dataset.power;drawOptimal();});}
 $('chart-note').textContent='Descriptive means of observed bags. Hover or focus a point for values. Select a heatmap cell to update the Explorer. Marginal means may hide time–power interactions.';
}
function combinations(rs,response){let all=[];for(let time of [90,120,150])for(let power of ['High','Medium'])for(let third of levels(rs,'third')){const a=rs.filter(r=>r.time===time&&r.power===power&&r.third===third);if(a.length)all.push({time,power,third,n:a.length,value:mean(a.map(r=>r[response]))});}return all.sort((a,b)=>response==='failed'?a.value-b.value:b.value-a.value);}
function drawOptimal(){let rs=rows(),response=$('response').value,sel=rs.filter(r=>r.time===+$('time').value&&r.power===$('power').value);if(!sel.length){$('optimal').innerHTML='<p>No bags remain for this setting. Choose another setting or include B-20.</p>';return;}let v=mean(sel.map(r=>r[response])),sd=sel.length>1?Math.sqrt(sel.reduce((s,r)=>s+(r[response]-v)**2,0)/(sel.length-1)):null,best=combinations(rs,response)[0];$('optimal').innerHTML=`<p class="eyebrow">SELECTED OBSERVATIONS · ${$('time').value}s / ${$('power').value}</p><div class="optimal-value">${fmt(v)}</div><p>Mean ${response==='failed'?'failed':'successful'} count per bag · n = ${sel.length} · SD = ${fmt(sd)}</p><p class="quiet">Range ${fmt(Math.min(...sel.map(r=>r[response])))}–${fmt(Math.max(...sel.map(r=>r[response])))}. Selecting All pools the two comparison groups within this study.</p><div class="rank"><span>Best complete treatment combination within the current filters:</span><b>${best.time}s / ${best.power} / ${best.third}</b><span>mean ${fmt(best.value)} · n = ${best.n}</span></div><p class="quiet">Choose best also selects the comparison group. Blocks are environmental filters, not optimization targets. No interpolation or extrapolation is used.</p>`;}
function renderModel(){let m=model();$('model-note').textContent=`Recomputed: ${m.formula.replaceAll('C(third)',state.exp==='A'?'Flavour':'Storage')}; n = ${m.diagnostics.length}; residual df = ${m.df}; R² = ${fmt(m.r2,4)}; RMSE = ${fmt(m.rmse)}。`;$('anova').innerHTML=m.anova.map(r=>`<tr><td>${r.term.replaceAll('C(third)',state.exp==='A'?'Flavour':'Storage')}</td><td>${r.df}</td><td>${fmt(r.ss)}</td><td>${fmt(r.ms)}</td><td>${fmt(r.F)}</td><td>${r.p==null?'—':r.p<.0001?r.p.toExponential(2):fmt(r.p,4)}</td></tr>`).join('');$('residual').innerHTML=svgPlot([{name:'Observations',points:m.diagnostics.map(p=>({x:p.fitted,y:p.residual,tip:p.id+' · Cook D '+fmt(p.cook,3)}))}],{width:520,height:310,scatter:true,zero:true,xlabel:'Fitted',ylabel:'Residual'});$('qq').innerHTML=svgPlot([{name:'Ordered residuals',points:m.qq}],{width:520,height:310,scatter:true,xlabel:'Normal theoretical quantile',ylabel:'Residual'});$('diagnostic-note').textContent=`Shapiro–Wilk p = ${fmt(m.shapiro_p,4)} . This does not prove normality or test independence. Interpret diagnostics alongside sample size and measurement uncertainty.${$('exclude').checked?'After excluding B-20, one treatment cell has a single bag. Cook distance can be undefined at unit leverage; shown as —.':''}`;}
function render(){let a=state.exp==='A',rs=rows(),response=$('response').value;
 $('design').innerHTML=a?'<b>FLAVOUR STUDY A / Does flavour affect yield?</b><br>3 times × 2 power levels × 2 flavours × 4 microwave blocks = 48 bags. One bag per treatment per block. A separate reference study; not pooled with B.':'<b>STORAGE STUDY B / Do older bags pop differently?</b><br>3 times × 2 power levels × 2 storage groups × 2 position blocks = 24 bags. One bag per treatment per block. Personal experiment, 2021.';
 $('warning').textContent=a?'Failed = unpopped + burnt. Successful counts and total kernel counts were not recorded; no success rate is calculated.':'Successful and failed counts are recorded. Failed combines unpopped and burnt. B-20 has overwritten handwriting; success is provisionally 40, consistent with archived numeric data.';
 $('metrics').innerHTML=[['Observed bags',rs.length],['Mean '+response,fmt(mean(rs.map(r=>r[response])))],['Treatment combinations',new Set(rs.map(r=>[r.time,r.power,r.third].join('|'))).size],['Blocks',levels(rs,'block').length]].map(([name,v])=>`<div class="metric"><small>${name}</small><strong>${v}</strong></div>`).join('');
 drawChart(rs,response);drawOptimal();renderModel();let keys=a?['id','time','power','third','block','unpopped','burnt','failed']:['id','time','power','third','block','success','failed'];$('data-head').innerHTML='<tr>'+keys.map(k=>`<th>${k==='third'?(a?'flavour':'storage'):k}</th>`).join('')+'<th>Note</th></tr>';
 $('data-body').innerHTML=rs.map(r=>'<tr>'+keys.map(k=>`<td>${r[k]}</td>`).join('')+`<td>${r.uncertain?'Overwritten success count; provisional reading':''}</td></tr>`).join('');$('row-count').textContent=rs.length+' bags / current selection';
 if(typeof renderComparison==='function')renderComparison();}

document.querySelectorAll('[data-exp]').forEach(b=>b.onclick=()=>changeExperiment(b.dataset.exp));document.querySelectorAll('[data-chart]').forEach(b=>b.onclick=()=>{state.chart=b.dataset.chart;document.querySelectorAll('[data-chart]').forEach(x=>x.setAttribute('aria-pressed',x===b));drawChart(rows(),$('response').value);});['response','third','block','exclude','factor'].forEach(id=>$(id).onchange=render);['time','power'].forEach(id=>$(id).onchange=drawOptimal);$('best').onclick=()=>{let b=combinations(rows(),$('response').value)[0];$('time').value=b.time;$('power').value=b.power;$('third').value=b.third;render();};
for(let i=0;i<15;i++){let e=document.createElement('i');e.className='kernel';e.style.cssText=`--x:${25+(i*17%50)}%;--d:${1.8+i*.12}s;animation-delay:${-i*.31}s`;$('kernels').append(e);}
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}}),{threshold:.08});document.querySelectorAll('section:not(.hero)').forEach(e=>{e.classList.add('reveal');observer.observe(e);});window.addEventListener('scroll',()=>{$('progress').style.width=100*window.scrollY/(document.documentElement.scrollHeight-innerHeight)+'%';},{passive:true});changeExperiment('B');
